WITH with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) AS prev_started_at FROM sessions), flagged AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessions_sessions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT country, DATE_TRUNC('MONTH', prev_started_at) AS activity_month, MIN(prev_started_at) AS first_seen, APPROX_PERCENTILE(new_group_flag, 0.9) AS new_group_flag_p90, (UNIX_TIMESTAMP(MAX(prev_started_at)) - UNIX_TIMESTAMP(MIN(prev_started_at))) / 60 AS span_minutes FROM sessions_sessions GROUP BY 1, 2 HAVING (UNIX_TIMESTAMP(MAX(prev_started_at)) - UNIX_TIMESTAMP(MIN(prev_started_at))) / 60 > 0 ORDER BY country DESC NULLS LAST;
